import 'server-only';

import { constants } from 'node:fs';
import { mkdir, open, realpath, unlink } from 'node:fs/promises';
import path from 'node:path';

/** Keys are opaque, generated by the application; never accept client paths. */
export interface FileStorage {
  put(key: string, bytes: Buffer): Promise<void>;
  get(key: string): Promise<Buffer>;
  remove(key: string): Promise<void>;
}

export function isMissingFile(error: unknown) {
  return (error as NodeJS.ErrnoException)?.code === 'ENOENT';
}

export class LocalFileStorage implements FileStorage {
  constructor(private readonly directory: string) {}

  private async filename(key: string) {
    if (!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\.bin$/.test(key)) {
      throw new Error('Invalid storage key.');
    }
    const root = path.resolve(this.directory);
    // Reject public paths before creating anything, and again after resolving symlinks.
    const check = (directory: string) => {
      for (const forbidden of ['public', '.next']) {
        const relative = path.relative(path.resolve(forbidden), directory);
        if (!relative || (!relative.startsWith('..') && !path.isAbsolute(relative))) {
          throw new Error('Attachment storage must be outside public/build directories.');
        }
      }
    };
    check(root);
    await mkdir(root, { recursive: true, mode: 0o700 });
    const resolved = await realpath(root);
    check(resolved);
    return path.join(resolved, key);
  }

  async put(key: string, bytes: Buffer) {
    const file = await open(await this.filename(key), 'wx', 0o600);
    try {
      await file.writeFile(bytes);
      await file.sync();
    } finally {
      await file.close();
    }
  }

  async get(key: string) {
    const file = await open(await this.filename(key), constants.O_RDONLY | constants.O_NOFOLLOW);
    try {
      if (!(await file.stat()).isFile()) {
        throw new Error('Invalid stored file.');
      }
      return await file.readFile();
    } finally {
      await file.close();
    }
  }

  async remove(key: string) {
    try {
      await unlink(await this.filename(key));
    } catch (error) {
      if (!isMissingFile(error)) {
        throw error;
      }
    }
  }
}

export function attachmentStorage(): FileStorage {
  const directory = process.env.VELA_ATTACHMENT_STORAGE_DIR;
  if (!directory && process.env.NODE_ENV === 'production') {
    throw new Error('VELA_ATTACHMENT_STORAGE_DIR is required in production.');
  }
  if (directory && !path.isAbsolute(directory)) {
    throw new Error('VELA_ATTACHMENT_STORAGE_DIR must be absolute.');
  }
  return new LocalFileStorage(directory ?? path.resolve('.local/attachments'));
}
